sys_script_include.script:
var EventUtils = Class.create();
EventUtils.prototype = {
    initialize: function(eventNumber) {
        this.eventNumber = eventNumber;
    },


    _getEventRecord: function() {
        var gr = new GlideRecord('x_1790139_event_ma_event_record'); 
        gr.addQuery('number', this.eventNumber);
        gr.query();
        if (gr.next()) {
            return gr;
        }
        return null;
    },


    getEventDetails: function() {
        return this._getEventRecord();
    },


    isVIP: function() {
        var gr = this._getEventRecord();
        if (gr) {
            return gr.getValue('x_is_vip') == 'true' || gr.getValue('x_is_vip') == '1';
        }
        return false;
    },


    getRemainingBudget: function() {
        var eventGR = this._getEventRecord();
        if (!eventGR) return 0;

        var gr = new GlideRecord('x_1790139_event_ma_budget');
        gr.addQuery('x_event_id', eventGR.getUniqueValue());
        gr.query();

        var totalBudget = 0;
        var totalSpent = 0;

        while (gr.next()) {
            totalBudget += parseFloat(gr.getValue('x_total_budget') || 0);
            totalSpent += parseFloat(gr.getValue('x_amount_spent') || 0);
        }

        return totalBudget - totalSpent;
    },

    // Fetch event tasks
   getEventTasks: function() {
        var eventGR = this._getEventRecord();
        if (!eventGR) return [];

        var tasks = [];
        var gr = new GlideRecord('x_1790139_event_ma_event_task'); 
        gr.addQuery('x_event_id', eventGR.getUniqueValue());
        gr.query();

        while (gr.next()) {
            tasks.push({
                number: gr.getDisplayValue('number'),
                task_name: gr.getDisplayValue('x_task_name'),
                status: gr.getDisplayValue('x_status')
            });
        }

        return tasks;
    },

    // Fetch event attendees
   getEventAttendees: function() {
        var eventGR = this._getEventRecord();
        if (!eventGR) return [];

        var attendees = [];
        var gr = new GlideRecord('x_1790139_event_ma_attendee');
        gr.addQuery('x_event_id', eventGR.getUniqueValue());
        gr.query();

        while (gr.next()) {
            attendees.push({
                attendee: gr.getDisplayValue('number')
            });
        }

        return attendees;
    },

    // Fetch event vendors
   getEventVendors: function() {
        var eventGR = this._getEventRecord();
        if (!eventGR) return [];

        var vendors = [];
        var gr = new GlideRecord('x_1790139_event_ma_vendor'); 
        gr.addQuery('x_event_id', eventGR.getUniqueValue());
        gr.query();

        while (gr.next()) {
            vendors.push({
                vendor: gr.getDisplayValue('number')
            });
        }

        return vendors;
    },

    // Fetch event budget details
    getEventBudgetDetails: function() {
        var eventGR = this._getEventRecord();
        if (!eventGR) return [];

        var gr = new GlideRecord('x_1790139_event_ma_budget');
        gr.addQuery('event', eventGR.getUniqueValue());
        gr.query();

        var budgets = [];
        while (gr.next()) {
            budgets.push({
                budgetName: gr.getDisplayValue('name'),
                allocated: gr.getValue('allocated_budget'),
                spent: gr.getValue('amount_spent')
            });
        }

        return budgets;
    },

    // Fetch event feedback
    getEventFeedback: function() {
        var eventGR = this._getEventRecord();
        if (!eventGR) return [];

        var feedbackList = [];
        var gr = new GlideRecord('x_1790139_event_ma_feedback'); // Replace with your feedback table
        gr.addQuery('x_event_id', eventGR.getUniqueValue());
        gr.query();

        while (gr.next()) {
            feedbackList.push({
                rating: gr.getValue('x_rating'),
                comments: gr.getValue('x_comments')
            });
        }

        return feedbackList;
    },

    type: 'EventUtils'
};
